
mkdir -p /opt/wechat-redeem/data
cd /opt/wechat-redeem

cat << 'EOF_B64' | base64 -d > /opt/wechat-redeem/app.py

EOF_B64

cat << 'EOF_DF' > /opt/wechat-redeem/Dockerfile
FROM python:3.11-slim
WORKDIR /app
RUN pip install --no-cache-dir fastapi uvicorn pydantic -i https://pypi.tuna.tsinghua.edu.cn/simple
COPY app.py /app/
EXPOSE 8000
VOLUME ["/data"]
CMD ["uvicorn", "app:app", "--host", "0.0.0.0", "--port", "8000"]
EOF_DF

docker build -t wechat-redeem:latest .
docker rm -f wechat-redeem 2>/dev/null || true
docker run -d --name wechat-redeem --restart always -p 8000:8000 -v /opt/wechat-redeem/data:/data wechat-redeem:latest
sleep 2
docker ps | grep wechat-redeem
curl -s http://127.0.0.1:8000/api/stats?pwd=REDACTED-PASSWORD
